import type {
  AcceptStoreInviteParams,
  Account,
  InviteStoreMemberParams,
  RemoveStoreMemberParams,
  ResendStoreInviteParams,
  AllowStoreEmailSendingParams,
  ChangeStoreMemberStatusParams,
  FindOwnStoreMembershipsParams,
  GetOwnStoreMembershipParams,
  LocationReach,
  PaginatedResponse,
  PauseStoreEmailSendingParams,
  Store,
  StoreEmailSending,
  StoreAccess,
  StoreMembership,
  StoreMembershipEditableStatus,
  StoreMembershipStatus,
  StoreMembershipWithStoreName,
  StorePermission,
  StorePermissionAccess,
  StoreRole,
  StoreMember,
  StoreMemberAccount,
  TransferStoreOwnershipParams,
  UpdateStoreMemberRolesParams,
} from "arky-sdk";
import type { createAdmin } from "arky-sdk/admin";
import type { EmailContact, EpochMilliseconds } from "arky-sdk";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Admin = ReturnType<typeof createAdmin>;

export type MembershipDiscoveryContracts = [
  Assert<Equal<ReturnType<Admin["store"]["member"]["getOwn"]>, Promise<StoreMembershipWithStoreName | null>>>,
  Assert<Equal<ReturnType<Admin["store"]["member"]["findOwn"]>, Promise<PaginatedResponse<StoreMembershipWithStoreName>>>>,
  Assert<Equal<NonNullable<Parameters<Admin["store"]["member"]["getOwn"]>[0]>, GetOwnStoreMembershipParams>>,
  Assert<Equal<NonNullable<Parameters<Admin["store"]["member"]["findOwn"]>[0]>, FindOwnStoreMembershipsParams>>,
  Assert<Equal<Parameters<Admin["store"]["member"]["updateRoles"]>[0], UpdateStoreMemberRolesParams>>,
  Assert<Equal<ReturnType<Admin["store"]["member"]["updateRoles"]>, Promise<StoreMembership>>>,
  Assert<Equal<Parameters<Admin["store"]["member"]["invite"]>[0], InviteStoreMemberParams>>,
  Assert<Equal<StoreMembership["role_ids"], string[]>>,
  Assert<Equal<StoreMember["account"], StoreMemberAccount | null>>,
  Assert<Equal<keyof StoreMemberAccount, "id" | "email">>,
  Assert<Equal<Awaited<ReturnType<Admin["store"]["member"]["find"]>>["items"][number], StoreMember>>,
  Assert<Missing<StoreMembership, "access" | "store_name" | "role" | "invitation_delivery_id" | "invitation_email_status">>,
  Assert<Equal<StoreMembershipWithStoreName["access"], StoreAccess>>,
  Assert<Equal<StoreAccess["permissions"], StorePermission[]>>,
  Assert<Equal<StoreMembershipWithStoreName["store_name"], string>>,
  Assert<RequiredField<InviteStoreMemberParams, "role_ids">>,
  Assert<RequiredField<InviteStoreMemberParams, "id">>,
  Assert<Equal<Parameters<Admin["store"]["member"]["resendInvite"]>[0], ResendStoreInviteParams>>,
  Assert<RequiredField<RemoveStoreMemberParams, "expected_updated_at">>,
  Assert<RequiredField<TransferStoreOwnershipParams, "expected_updated_at">>,
  Assert<Missing<InviteStoreMemberParams, "access" | "role" | "email">>,
  Assert<Equal<InviteStoreMemberParams["contact"], EmailContact>>,
  Assert<Equal<StorePermission["type"], "admin" | "payments" | "packages" | "orders" | "customers" | "fulfillment" | "inventory" | "marketing" | "public_collections" | "collection" | "support" | "email" | "analytics">>,
  Assert<Equal<Extract<StorePermission, { type: "fulfillment" }>["locations"], LocationReach>>,
  Assert<Equal<Extract<StorePermission, { type: "inventory" }>["locations"], LocationReach>>,
  Assert<Missing<Extract<StorePermission, { type: "orders" }>, "locations">>,
  Assert<Equal<StorePermissionAccess, "write" | "read">>,
  Assert<Equal<Extract<StorePermission, { type: "orders" }>, { type: "orders"; access: StorePermissionAccess }>>,
  Assert<Equal<Extract<StorePermission, { type: "payments" }>, { type: "payments"; access: StorePermissionAccess }>>,
  Assert<Equal<Extract<StorePermission, { type: "customers" }>, { type: "customers"; access: StorePermissionAccess }>>,
  Assert<RequiredField<Extract<StorePermission, { type: "orders" }>, "access">>,
  Assert<Missing<Extract<StorePermission, { type: "packages" | "marketing" | "admin" }>, "access">>,
  Assert<Equal<LocationReach, { type: "everywhere" } | { type: "only"; store_location_ids: string[] }>>,
  Assert<Missing<StoreRole, "status">>,
  Assert<Equal<keyof Admin["store"]["role"], "create" | "update" | "get" | "find" | "delete">>,
  Assert<Equal<Parameters<Admin["store"]["member"]["transferOwnership"]>[0], TransferStoreOwnershipParams>>,
  Assert<Equal<ReturnType<Admin["store"]["member"]["transferOwnership"]>, Promise<Store>>>,
  Assert<Equal<Parameters<Admin["store"]["member"]["changeStatus"]>[0], ChangeStoreMemberStatusParams>>,
  Assert<Equal<ReturnType<Admin["store"]["member"]["changeStatus"]>, Promise<StoreMembership>>>,
  Assert<Equal<ChangeStoreMemberStatusParams["status"], StoreMembershipEditableStatus>>,
  Assert<Equal<StoreMembershipEditableStatus, { type: "active" } | { type: "disabled" }>>,
  Assert<Equal<StoreMembershipStatus, { type: "invited"; contact: EmailContact } | { type: "active"; account_id: string } | { type: "disabled"; account_id: string }>>,
  Assert<Equal<Parameters<Admin["store"]["member"]["acceptInvite"]>[0], AcceptStoreInviteParams>>,
  Assert<Equal<ReturnType<Admin["store"]["member"]["acceptInvite"]>, Promise<StoreMembership>>>,
  Assert<Equal<keyof AcceptStoreInviteParams, "store_id" | "expected_updated_at">>,
  Assert<Equal<Parameters<Admin["store"]["pauseEmailSending"]>[0], PauseStoreEmailSendingParams>>,
  Assert<Equal<keyof PauseStoreEmailSendingParams, "store_id" | "expected_updated_at" | "reason">>,
  Assert<Equal<Parameters<Admin["store"]["allowEmailSending"]>[0], AllowStoreEmailSendingParams>>,
  Assert<Equal<ReturnType<Admin["store"]["allowEmailSending"]>, Promise<Store>>>,
  Assert<Equal<Store["email_sending"], StoreEmailSending>>,
  Assert<Equal<Extract<Store["type"], { type: "live" }>["account_id"], string>>,
  Assert<Missing<Store, "owner_account_id" | "mode">>,
  Assert<Missing<Admin["store"], "buildHook">>,
  Assert<Equal<Account["status"], { type: "active" } | { type: "deleting" }>>,
];
